	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, '5' ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, true ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, false ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, null ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, void 0 ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, [] ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, {} ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, ( x: number ): number => x ); // $ExpectError
