// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const iseed = new Int32Array( [ 0, 1, 2, 3 ] );
	const x = new Float64Array( 5 );

	dlarnv.ndarray(); // $ExpectError
	dlarnv.ndarray( 1 ); // $ExpectError
	dlarnv.ndarray( 1, iseed ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1 ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0 ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5 ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1 ); // $ExpectError
	dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, 0, 10 ); // $ExpectError
}
